// Design Token 类型定义
/** 规范版本：默认值/结构变更后递增，旧 localStorage 缓存自动失效并采用新默认 */
export const TOKEN_VERSION = 9;

export type ThemeMode = 'light' | 'dark';

export interface ColorState {
  base: string;
  hover: string;
  pressed: string;
  active: string;
}

export interface SemanticColors {
  info: ColorState;
  success: ColorState;
  warning: ColorState;
  danger: ColorState;
}

export interface DesignTokens {
  theme: ThemeMode;
  colors: {
    primary: string;
    primaryLight: string;
    primaryDark: string;
    secondary: string;
    accent: string;
    success: string;
    warning: string;
    error: string;
    bgBase: string;
    bgSurface: string;
    bgElevated: string;
    bgHover: string;
    bgActive: string;
    textPrimary: string;
    textSecondary: string;
    textMuted: string;
    textInverse: string;
    borderDefault: string;
    borderHover: string;
    borderActive: string;
  };
  fonts: {
    sans: string;
    mono: string;
  };
  fontSizes: {
    xs: string;
    sm: string;
    base: string;
    lg: string;
    xl: string;
    '2xl': string;
    '3xl': string;
    '4xl': string;
    '5xl': string;
  };
  lineHeights: {
    tight: string;
    snug: string;
    normal: string;
    relaxed: string;
    loose: string;
  };
  spacing: {
    xs: string;
    s: string;
    m: string;
    l: string;
    xl: string;
    xxl: string;
    xxxl: string;
  };
  radii: {
    xs: string;
    s: string;
    m: string;
    l: string;
    xl: string;
    xxl: string;
    full: string;
  };
  // 控件高度阶梯（用户定档 2026-09-30）：小 32 / 标准 40（scrubber 行条、主按钮）/ 大 48
  controlSizes: {
    sm: string;
    md: string;
    lg: string;
  };
  shadows: {
    sm: string;
    md: string;
    lg: string;
    xl: string;
  };
  semantic: SemanticColors;
}

/* ============ 色彩派生引擎：主色 → 全局色彩体系 ============ */

export function hexToHsl(hex: string): { h: number; s: number; l: number } {
  let hh = String(hex || '').replace('#', '');
  if (hh.length === 3) hh = hh.split('').map(c => c + c).join('');
  const n = parseInt(hh.slice(0, 6), 16);
  if (Number.isNaN(n)) return { h: 0, s: 0, l: 50 };
  const r = ((n >> 16) & 255) / 255, g = ((n >> 8) & 255) / 255, b = (n & 255) / 255;
  const max = Math.max(r, g, b), min = Math.min(r, g, b);
  const l = (max + min) / 2;
  const d = max - min;
  const s = d === 0 ? 0 : d / (1 - Math.abs(2 * l - 1));
  let h = 0;
  if (d !== 0) {
    if (max === r) h = ((g - b) / d) % 6;
    else if (max === g) h = (b - r) / d + 2;
    else h = (r - g) / d + 4;
    h *= 60;
    if (h < 0) h += 360;
  }
  return { h: Math.round(h), s: Math.round(s * 100), l: Math.round(l * 100) };
}

export function hslToHex(h: number, s: number, l: number): string {
  const ss = Math.max(0, Math.min(100, s)) / 100;
  const ll = Math.max(0, Math.min(100, l)) / 100;
  const hh = ((h % 360) + 360) % 360;
  const c = (1 - Math.abs(2 * ll - 1)) * ss;
  const x = c * (1 - Math.abs(((hh / 60) % 2) - 1));
  const m = ll - c / 2;
  let rgb: [number, number, number];
  if (hh < 60) rgb = [c, x, 0];
  else if (hh < 120) rgb = [x, c, 0];
  else if (hh < 180) rgb = [0, c, x];
  else if (hh < 240) rgb = [0, x, c];
  else if (hh < 300) rgb = [x, 0, c];
  else rgb = [c, 0, x];
  const to = (v: number) => Math.round((v + m) * 255).toString(16).padStart(2, '0');
  return `#${to(rgb[0])}${to(rgb[1])}${to(rgb[2])}`;
}

/**
 * 从主色派生品牌色家族（primaryLight/Dark/secondary/accent/textInverse）；
 * 中性色（背景/文字/边框）= reactbits 同款固定色板（2026-09-30 用户规范：去色倾向）。
 */
export function deriveThemeColors(primary: string, theme: ThemeMode = 'dark'): Omit<DesignTokens['colors'], 'success' | 'warning' | 'error'> {
  const { h, s, l } = hexToHsl(primary);
  const primaryLight = hslToHex(h, s, Math.min(l + 12, 90));
  const primaryDark = hslToHex(h, s, Math.max(l - 15, 10));
  // 用户规范：辅助色/强调色与主色统一（改主色时仍跟随联动）
  const secondary = primary;
  const accent = primary;
  // 亮色主色（l>45）上用深色文字，暗色主色上用白色文字
  const textInverse = l > 45 ? hslToHex(h, Math.min(s, 35), 9) : '#ffffff';

  if (theme === 'light') {
    // 亮色：中性白灰（无色倾向）
    return {
      primary, primaryLight, primaryDark, secondary, accent, textInverse,
      bgBase: '#ffffff',
      bgSurface: '#fafafa',
      bgElevated: '#f4f4f5',
      bgHover: '#ececef',
      bgActive: '#e4e4e7',
      textPrimary: '#18181b',
      textSecondary: '#3f3f46',
      textMuted: '#71717a',
      borderDefault: '#e4e4e7',
      borderHover: '#d4d4d8',
      borderActive: primary,
    };
  }
  // 暗色：纯中性灰阶（零色彩倾向，明度层级同 reactbits #120f17 体系，2026-10-01 用户要求去紫倾向）
  return {
    primary, primaryLight, primaryDark, secondary, accent, textInverse,
    bgBase: '#141414',
    bgSurface: '#1d1d1d',
    bgElevated: '#252525',
    bgHover: '#3a3a3a',
    bgActive: '#2d2d2d',
    textPrimary: '#ffffff',
    textSecondary: '#e4e4e4',
    textMuted: '#a1a1a1',
    borderDefault: '#323232',
    borderHover: '#3f3f3f',
    borderActive: primary,
  };
}

/** 当前品牌主色 */
export const PRIMARY_BRAND = '#a9fd1c';

/** 运行时解析 CSS 变量（供 Canvas 类组件取品牌色） */
export function resolveToken(name: string, fallback = '#ffffff'): string {
  if (typeof document === 'undefined') return fallback;
  const v = getComputedStyle(document.documentElement).getPropertyValue(name).trim();
  return v || fallback;
}

// 官方色阶（取自用户 Figma 设计规范图，编号即色阶档位）
export const colorPalettes = {
  blue:   { 1: '#060c4a', 4: '#2a44c0', 5: '#4c6be8', 6: '#5b78e8', 7: '#8098ed', 10: '#dce6fa' },
  green:  { 1: '#143a1e', 4: '#4fa85b', 5: '#6ec474', 6: '#7bc97f', 7: '#98d79c', 10: '#eaf7eb' },
  yellow: { 1: '#452a0c', 4: '#c08542', 5: '#e2a85b', 6: '#e5b26b', 7: '#edcb90', 10: '#f7f0e3' },
  red:    { 1: '#400b09', 4: '#aa4038', 5: '#c15149', 6: '#c96058', 7: '#da8e87', 10: '#f7ecea' },
} as const;

// 功能色预设：按颜色规范结构（base/hover/pressed/active × 双模式）
export function buildSemanticColors(theme: ThemeMode): SemanticColors {
  const p = colorPalettes;
  if (theme === 'light') {
    return {
      info:    { base: p.blue[5],   hover: p.blue[6],   pressed: p.blue[4],   active: p.blue[10] },
      success: { base: p.green[5],  hover: p.green[6],  pressed: p.green[4],  active: p.green[10] },
      warning: { base: p.yellow[5], hover: p.yellow[6], pressed: p.yellow[4], active: p.yellow[10] },
      danger:  { base: p.red[5],    hover: p.red[6],    pressed: p.red[4],    active: p.red[10] },
    };
  }
  return {
    info:    { base: p.blue[6],   hover: p.blue[5],   pressed: p.blue[7],   active: p.blue[1] },
    success: { base: p.green[6],  hover: p.green[5],  pressed: p.green[7],  active: p.green[1] },
    warning: { base: p.yellow[6], hover: p.yellow[5], pressed: p.yellow[7], active: p.yellow[1] },
    danger:  { base: p.red[6],    hover: p.red[5],    pressed: p.red[7],    active: p.red[1] },
  };
}

// 默认 Token 值（色彩由品牌主色自动派生）
export const defaultTokens: DesignTokens = {
  theme: 'dark',
  colors: {
    ...deriveThemeColors(PRIMARY_BRAND, 'dark'),
    success: '#10b981',
    warning: '#f59e0b',
    error: '#ef4444',
  },
  fonts: {
    sans: "'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif",
    mono: "'JetBrains Mono', 'Fira Code', monospace",
  },
  fontSizes: {
    // 字体规范：取自 Figma APY 页面实测配对（字号/行高）
    xs: '0.75rem',    // 12/16 caption
    sm: '0.875rem',   // 14/20 正文
    base: '1rem',     // 16/24 子标题
    lg: '1.25rem',    // 20/28 中标题
    xl: '1.5rem',     // 24/32 大标题
    '2xl': '1.75rem', // 28/34
    '3xl': '2rem',    // 32/40
    '4xl': '2.5rem',  // 40/48 页面标题（设计稿最大档）
    '5xl': '2.5rem',  // 同 4xl，hero 用
  },
  lineHeights: {
    tight: '1.2',     // 40/48、28/34 大标题
    snug: '1.25',     // 32/40、24/32
    normal: '1.43',   // 14/20 正文
    relaxed: '1.5',   // 16/24、12/16
    loose: '2',
  },
  spacing: {
    xs: '4px',
    s: '8px',
    m: '12px',
    l: '16px',
    xl: '20px',
    xxl: '24px',
    xxxl: '32px',
  },
  radii: {
    // 圆角规范：以卡片为基准（xxl=24px），卡片内部每向内一层递进缩小一档，最小 xs=4px；full 用于胶囊/圆形
    xs: '4px',
    s: '8px',
    m: '12px',
    l: '16px',
    xl: '20px',
    xxl: '24px',
    full: '999px',
  },
  controlSizes: {
    sm: '32px',
    md: '40px',
    lg: '48px',
  },
  shadows: {
    sm: '0 1px 2px rgba(0, 0, 0, 0.3)',
    md: '0 4px 6px -1px rgba(0, 0, 0, 0.4), 0 2px 4px -2px rgba(0, 0, 0, 0.3)',
    lg: '0 10px 15px -3px rgba(0, 0, 0, 0.5), 0 4px 6px -4px rgba(0, 0, 0, 0.3)',
    xl: '0 20px 25px -5px rgba(0, 0, 0, 0.5), 0 8px 10px -6px rgba(0, 0, 0, 0.3)',
  },
  semantic: buildSemanticColors('dark'),
};

// 将 Token 应用到 CSS Variables
export function applyTokensToCSS(tokens: DesignTokens) {
  const root = document.documentElement;
  const style = root.style;

  // Colors
  style.setProperty('--color-primary', tokens.colors.primary);
  style.setProperty('--color-primary-light', tokens.colors.primaryLight);
  style.setProperty('--color-primary-dark', tokens.colors.primaryDark);
  style.setProperty('--color-secondary', tokens.colors.secondary);
  style.setProperty('--color-accent', tokens.colors.accent);
  style.setProperty('--color-success', tokens.colors.success);
  style.setProperty('--color-warning', tokens.colors.warning);
  style.setProperty('--color-error', tokens.colors.error);
  style.setProperty('--color-bg-base', tokens.colors.bgBase);
  style.setProperty('--color-bg-surface', tokens.colors.bgSurface);
  style.setProperty('--color-bg-elevated', tokens.colors.bgElevated);
  style.setProperty('--color-bg-hover', tokens.colors.bgHover);
  style.setProperty('--color-bg-active', tokens.colors.bgActive);
  style.setProperty('--color-text-primary', tokens.colors.textPrimary);
  style.setProperty('--color-text-secondary', tokens.colors.textSecondary);
  style.setProperty('--color-text-muted', tokens.colors.textMuted);
  style.setProperty('--color-text-inverse', tokens.colors.textInverse);
  style.setProperty('--color-border-default', tokens.colors.borderDefault);
  style.setProperty('--color-border-hover', tokens.colors.borderHover);
  style.setProperty('--color-border-active', tokens.colors.borderActive);

  // Fonts
  style.setProperty('--font-sans', tokens.fonts.sans);
  style.setProperty('--font-mono', tokens.fonts.mono);

  // Font Sizes
  style.setProperty('--text-xs', tokens.fontSizes.xs);
  style.setProperty('--text-sm', tokens.fontSizes.sm);
  style.setProperty('--text-base', tokens.fontSizes.base);
  style.setProperty('--text-lg', tokens.fontSizes.lg);
  style.setProperty('--text-xl', tokens.fontSizes.xl);
  style.setProperty('--text-2xl', tokens.fontSizes['2xl']);
  style.setProperty('--text-3xl', tokens.fontSizes['3xl']);
  style.setProperty('--text-4xl', tokens.fontSizes['4xl']);
  style.setProperty('--text-5xl', tokens.fontSizes['5xl']);

  // Line Heights
  style.setProperty('--leading-tight', tokens.lineHeights.tight);
  style.setProperty('--leading-snug', tokens.lineHeights.snug);
  style.setProperty('--leading-normal', tokens.lineHeights.normal);
  style.setProperty('--leading-relaxed', tokens.lineHeights.relaxed);
  style.setProperty('--leading-loose', tokens.lineHeights.loose);

  // Spacing: 新阶梯命名 + 旧数字别名同步（站内大量组件仍使用 --space-4 等）
  Object.entries(tokens.spacing).forEach(([key, value]) => {
    style.setProperty(`--space-${key}`, value);
  });
  const spacingAlias: Record<string, string> = {
    '1': tokens.spacing.xs,
    '2': tokens.spacing.s,
    '3': tokens.spacing.m,
    '4': tokens.spacing.l,
    '5': tokens.spacing.xl,
    '6': tokens.spacing.xxl,
    '8': tokens.spacing.xxxl,
    // 大间距 = 规范档位组合/倍数（随阶梯调整自动联动，不再出现规范外的固定值）
    '10': 'calc(var(--space-xxl) + var(--space-l))',      // 24+16=40
    '12': 'calc(var(--space-xxl) * 2)',                   // 48
    '16': 'calc(var(--space-xxxl) * 2)',                  // 64
    '20': 'calc(var(--space-xxxl) * 2 + var(--space-xxxl) * 0.5)', // 80
  };
  Object.entries(spacingAlias).forEach(([key, value]) => {
    style.setProperty(`--space-${key}`, value);
  });

  // Radii: 旧名称映射到规范层级（卡片 24 → 一级内嵌 16 → 控件 12 → 小元素 8 → 最小 4）
  style.setProperty('--radius-xs', tokens.radii.xs);
  style.setProperty('--radius-s', tokens.radii.s);
  style.setProperty('--radius-m', tokens.radii.m);
  style.setProperty('--radius-l', tokens.radii.l);
  style.setProperty('--radius-xl', tokens.radii.xl);
  style.setProperty('--radius-xxl', tokens.radii.xxl);
  style.setProperty('--radius-full', tokens.radii.full);
  const radiusAlias: Record<string, string> = {
    sm: tokens.radii.xs,   // 4  最小元素
    md: tokens.radii.s,    // 8  小元素
    lg: tokens.radii.m,    // 12 控件（输入框/按钮）
    '2xl': tokens.radii.xxl, // 24 卡片基准
    // xl 不别名：保留规范值 20px
  };
  Object.entries(radiusAlias).forEach(([key, value]) => {
    style.setProperty(`--radius-${key}`, value);
  });

  // Shadows
  style.setProperty('--shadow-sm', tokens.shadows.sm);
  style.setProperty('--shadow-md', tokens.shadows.md);
  style.setProperty('--shadow-lg', tokens.shadows.lg);
  style.setProperty('--shadow-xl', tokens.shadows.xl);

  // Semantic 功能色（info/success/warning/danger × base/hover/pressed/active）
  if (tokens.semantic) {
    for (const [group, states] of Object.entries(tokens.semantic)) {
      for (const [state, value] of Object.entries(states as Record<string, string>)) {
        style.setProperty(`--color-${group}${state === 'base' ? '' : `-${state}`}`, value);
      }
    }
  }

  // 控件高度阶梯
  style.setProperty('--control-sm', tokens.controlSizes.sm);
  style.setProperty('--control-md', tokens.controlSizes.md);
  style.setProperty('--control-lg', tokens.controlSizes.lg);

  // 导航悬浮遮罩（reactbits surface-ghost）：暗色=白 7%，亮色=黑 5%
  style.setProperty('--color-hover-overlay', tokens.theme === 'dark' ? 'rgba(255, 255, 255, 0.05)' : 'rgba(24, 24, 27, 0.04)');
}

// 导出 Token 为 JSON
export function exportTokensAsJSON(tokens: DesignTokens): string {
  return JSON.stringify(tokens, null, 2);
}

// 导出 Token 为 CSS Variables
export function exportTokensAsCSS(tokens: DesignTokens): string {
  return `:root {
  /* Colors */
  --color-primary: ${tokens.colors.primary};
  --color-primary-light: ${tokens.colors.primaryLight};
  --color-primary-dark: ${tokens.colors.primaryDark};
  --color-secondary: ${tokens.colors.secondary};
  --color-accent: ${tokens.colors.accent};
  --color-bg-base: ${tokens.colors.bgBase};
  --color-bg-surface: ${tokens.colors.bgSurface};
  --color-bg-elevated: ${tokens.colors.bgElevated};
  --color-text-primary: ${tokens.colors.textPrimary};
  --color-text-secondary: ${tokens.colors.textSecondary};
  --color-border-default: ${tokens.colors.borderDefault};

  /* Fonts */
  --font-sans: ${tokens.fonts.sans};
  --font-mono: ${tokens.fonts.mono};

  /* Font Sizes */
  --text-xs: ${tokens.fontSizes.xs};
  --text-sm: ${tokens.fontSizes.sm};
  --text-base: ${tokens.fontSizes.base};
  --text-lg: ${tokens.fontSizes.lg};
  --text-xl: ${tokens.fontSizes.xl};
  --text-2xl: ${tokens.fontSizes['2xl']};
  --text-3xl: ${tokens.fontSizes['3xl']};

  /* Spacing */
  --space-xs: ${tokens.spacing.xs};
  --space-s: ${tokens.spacing.s};
  --space-m: ${tokens.spacing.m};
  --space-l: ${tokens.spacing.l};
  --space-xl: ${tokens.spacing.xl};
  --space-xxl: ${tokens.spacing.xxl};
  --space-xxxl: ${tokens.spacing.xxxl};

  /* Radii */
  --radius-xs: ${tokens.radii.xs};
  --radius-s: ${tokens.radii.s};
  --radius-m: ${tokens.radii.m};
  --radius-l: ${tokens.radii.l};
  --radius-xl: ${tokens.radii.xl};
  --radius-xxl: ${tokens.radii.xxl};
  --radius-full: ${tokens.radii.full};

  /* Control Heights */
  --control-sm: ${tokens.controlSizes.sm};
  --control-md: ${tokens.controlSizes.md};
  --control-lg: ${tokens.controlSizes.lg};

  /* Semantic Colors (theme: ${tokens.theme}) */
${Object.entries(tokens.semantic).map(([g, s]) => `  --color-${g}: ${s.base};\n  --color-${g}-hover: ${s.hover};\n  --color-${g}-pressed: ${s.pressed};\n  --color-${g}-active: ${s.active};`).join('\n')}
}`;
}
